// Minimal gating decision based on CKNE and SLA
function decideForward(tenant, ckne, inFlight, sla) {
  const degraded = ckne.overall < 0.7;
  const batch = degraded ? Math.max(1, Math.floor(tenant.baseBatch * 0.5)) : tenant.baseBatch;
  const forwardRaw = !degraded || sla === 'premium';
  return { batch, forwardRaw };
}
```

